/*
  POIATO GESTÃO — PORTFÓLIO PÚBLICO
  Aplicação demonstrativa independente. Todos os registros são fictícios.
  Nenhuma dependência, dado, integração ou trecho do sistema empresarial de origem.
*/
'use strict';
const KEY = 'poiato-gestao-portfolio-v2';
const $ = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
const id = prefix => prefix + '-' + Math.random().toString(36).slice(2,9);
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const number = n => new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(Number(n)||0);
const esc = t => String(t==null?'':t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = t => t ? new Date(t).toLocaleString('pt-BR') : '—';
const pct = n => number(n)+'%';
const round = v => Math.round(v*100)/100;
const fresh = () => ({
  products:[
    {id:'p01',code:'PRD-101',name:'Componente de articulação modular',category:'Componentes',size:'Único',supplier:'Fabricante Exemplo A',cost:2450,active:true},
    {id:'p02',code:'PRD-102',name:'Interface de silicone',category:'Interfaces',size:'M',supplier:'Fabricante Exemplo B',cost:485,active:true},
    {id:'p03',code:'PRD-103',name:'Pé de resposta dinâmica',category:'Pés',size:'26',supplier:'Fabricante Exemplo A',cost:1240,active:true},
    {id:'p04',code:'PRD-104',name:'Articulação hidráulica',category:'Componentes',size:'Único',supplier:'Fabricante Exemplo A',cost:4790,active:true},
    {id:'p05',code:'PRD-105',name:'Suspensão com trava',category:'Acessórios',size:'Único',supplier:'Fabricante Exemplo B',cost:370,active:true},
    {id:'p06',code:'PRD-106',name:'Adaptador de conexão',category:'Acessórios',size:'Único',supplier:'Fabricante Exemplo C',cost:320,active:true},
    {id:'p07',code:'PRD-107',name:'Interface de silicone reforçada',category:'Interfaces',size:'L',supplier:'Fabricante Exemplo B',cost:680,active:true},
    {id:'p08',code:'PRD-108',name:'Pé multiaxial',category:'Pés',size:'25',supplier:'Fabricante Exemplo C',cost:955,active:true},
    {id:'p09',code:'PRD-109',name:'Capa de proteção',category:'Acessórios',size:'Único',supplier:'Fabricante Exemplo C',cost:185,active:true}
  ],
  bids:[
    {id:'b01',number:'PE 021/2026',agency:'Instituição Pública Alfa',contract:'CT-014/2026',process:'PR-082/2026',status:'Vigente',items:[{id:'i01',number:'01',description:'Conjunto de prótese modular',category:'Conjunto',qty:8,value:16800},{id:'i02',number:'02',description:'Componente de articulação',category:'Componentes',qty:12,value:8300},{id:'i03',number:'03',description:'Interface protética',category:'Interfaces',qty:25,value:2100}]},
    {id:'b02',number:'PE 047/2026',agency:'Instituição Pública Beta',contract:'CT-029/2026',process:'PR-135/2026',status:'Vigente',items:[{id:'i04',number:'01',description:'Pé protético dinâmico',category:'Pés',qty:10,value:5400},{id:'i05',number:'02',description:'Conjunto de suspensão',category:'Acessórios',qty:15,value:2800}]},
    {id:'b03',number:'PE 062/2026',agency:'Instituição Pública Gama',contract:'CT-038/2026',process:'PR-206/2026',status:'Encerrado',items:[{id:'i06',number:'01',description:'Componentes e acessórios',category:'Acessórios',qty:7,value:1900}]},
    {id:'b04',number:'PE 075/2026',agency:'Instituição Pública Delta',contract:'CT-044/2026',process:'PR-240/2026',status:'Vigente',items:[{id:'i07',number:'01',description:'Prótese modular e acessórios',category:'Conjunto',qty:4,value:14800}]}
  ],
  clients:[
    {id:'c01',name:'Atendimento Exemplo 001',city:'Cidade Modelo',bidId:'b01',status:'Em andamento',date:'2026-10-06',notes:'Avaliação técnica concluída. Dados fictícios.',deleted:false,supplies:[{id:'s01',itemId:'i01',productId:'p01',qty:1,size:'M',logistics:420,other:120},{id:'s02',itemId:'i01',productId:'p02',qty:1,size:'M',logistics:0,other:0}]},
    {id:'c02',name:'Atendimento Exemplo 002',city:'Cidade Modelo',bidId:'b01',status:'Entregue',date:'2026-10-07',notes:'Entrega fictícia registrada.',deleted:false,supplies:[{id:'s03',itemId:'i02',productId:'p04',qty:1,size:'Único',logistics:250,other:75}]},
    {id:'c03',name:'Atendimento Exemplo 003',city:'Outra Cidade',bidId:'b02',status:'Em andamento',date:'2026-10-09',notes:'Aguardando conferência.',deleted:false,supplies:[{id:'s04',itemId:'i04',productId:'p03',qty:1,size:'26',logistics:310,other:0}]},
    {id:'c04',name:'Atendimento Exemplo 004',city:'Cidade Modelo',bidId:'b02',status:'Pendente',date:'2026-10-11',notes:'Sem produto associado.',deleted:false,supplies:[]},
    {id:'c05',name:'Atendimento Exemplo 005',city:'Cidade Exemplo',bidId:'b01',status:'Entregue',date:'2026-10-14',notes:'Registro ilustrativo.',deleted:false,supplies:[{id:'s05',itemId:'i03',productId:'p07',qty:1,size:'L',logistics:95,other:0}]},
    {id:'c06',name:'Atendimento Exemplo 006',city:'Cidade Exemplo',bidId:'b04',status:'Em andamento',date:'2026-10-16',notes:'Registro de demonstração.',deleted:false,supplies:[{id:'s06',itemId:'i07',productId:'p03',qty:1,size:'25',logistics:280,other:50}]},
    {id:'c07',name:'Atendimento Exemplo 007',city:'Cidade Modelo',bidId:'b02',status:'Entregue',date:'2026-10-18',notes:'Registro ilustrativo.',deleted:false,supplies:[{id:'s07',itemId:'i05',productId:'p05',qty:1,size:'Único',logistics:70,other:0}]}
  ],
  users:[{id:'u1',name:'Administrador Demo',role:'admin',status:'Ativo'},{id:'u2',name:'Operador Demo',role:'user',status:'Ativo'},{id:'u3',name:'Consulta Demo',role:'guest',status:'Ativo'}],
  audit:[{at:'2026-10-26T11:35:00',actor:'Administrador Demo',area:'Produtos',description:'Custo de item fictício consultado'},{at:'2026-10-26T09:05:00',actor:'Operador Demo',area:'Cadastros',description:'Atendimento de exemplo atualizado'}]
});
let state;
try {const saved=JSON.parse(localStorage.getItem(KEY));state=saved && saved.products && saved.clients && saved.bids?saved:fresh()}catch{state=fresh()}
let role='admin',page='dashboard',selectedClient=null,selectedBid=null,detailTab='resumo',bidTab='itens',reportType='pregao',moneyVisible=false,filters={clients:'',status:'Todos',products:'',bids:'',audit:''},showDeleted=false;
const save =()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}};
const bidFor = cid => state.bids.find(b=>b.id===cid);
const itemFor = iid => state.bids.flatMap(b=>b.items.map(i=>({...i,bidId:b.id}))).find(i=>i.id===iid);
const productFor = pid => state.products.find(p=>p.id===pid);
const activeClients=()=>state.clients.filter(c=>!c.deleted);
const priceOf = c => {const grouped={};c.supplies.forEach(s=>{if(s.itemId){const item=itemFor(s.itemId);if(item)grouped[item.id]=item.value}});return Object.values(grouped).reduce((a,b)=>a+b,0)};
const costOf=c=>c.supplies.reduce((sum,s)=>sum+(Number(productFor(s.productId)?.cost)||0)*s.qty+Number(s.logistics||0)+Number(s.other||0),0);
const sumVigente=()=>activeClients().reduce((n,c)=>n+priceOf(c),0);
const sumCosts=()=>activeClients().reduce((n,c)=>n+costOf(c),0);
const costParts=()=>activeClients().flatMap(c=>c.supplies).reduce((n,s)=>n+(productFor(s.productId)?.cost||0)*s.qty,0);
const totalContracts=()=>state.bids.reduce((x,b)=>x+b.items.reduce((a,i)=>a+i.qty*i.value,0),0);
const itemUsage=iid=>activeClients().reduce((n,c)=>n+Number(c.supplies.some(s=>s.itemId===iid)),0);
const supplierCount=()=>new Set(state.products.filter(p=>p.active).map(p=>p.supplier)).size;
const statusBadge=s=>`<span class="badge ${s==='Entregue'||s==='Vigente'||s==='Ativo'?'green':s==='Pendente'?'amber':s==='Encerrado'||s==='Excluído'?'red':''}">${esc(s)}</span>`;
const onlyAdmin=()=>role==='admin';const editable=()=>role!=='guest';
function note(area,description){state.audit.unshift({at:new Date().toISOString(),actor:role==='admin'?'Administrador Demo':'Operador Demo',area,description});state.audit=state.audit.slice(0,70);save()}
function toast(txt){let el=$('#toast');el.textContent=txt;el.classList.add('visible');clearTimeout(window._toast);window._toast=setTimeout(()=>el.classList.remove('visible'),2900)}
function navigate(to){page=to;selectedClient=null;selectedBid=null;detailTab='resumo';bidTab='itens';$$('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===to));render();$('#main').scrollTop=0;}
function viewHeader(title,subtitle,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function panel(title,body,extra=''){return `<section class="panel"><div class="panelhead"><h2>${title}</h2>${extra}</div>${body}</section>`}
function table(headers,rows,empty='Nenhum registro para os filtros selecionados.'){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
function moneyMask(v){return moneyVisible?money(v):'••••••'}
function render(){let html='';switch(page){case'dashboard':html=dashboard();break;case'cadastros':html=cadastros();break;case'novo':html=novo();break;case'produtos':html=produtos();break;case'performance':html=performance();break;case'pregoes':html=pregoes();break;case'relatorios':html=relatorios();break;case'auditoria':html=auditoria();break;case'lixeira':html=lixeira();break;case'backup':html=backup();break;case'usuarios':html=usuarios();break;default:html=dashboard()};$('#view').innerHTML=html;$$('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===page));}
function dashboard(){const vigente=sumVigente(),cost=sumCosts(),margin=vigente-cost,parts=costParts();const cards=[['VALOR VIGENTE',vigente,'Atendimentos vinculados a itens','#27dd9c'],['CUSTO INTERNO',cost,'Produtos + logística + demais custos','#f7ad40'],['MARGEM VIGENTE',margin,'Receita vigente menos custos','#37caff'],['MARGEM %',vigente?100*margin/vigente:0,'Resultado proporcional','#4ac0ff'],['MARKUP MÉDIO',parts?100*(vigente-parts)/parts:0,'Comparação sobre custo de produtos','#bb85fb'],['CUSTOS DE PRODUTOS',parts,'Custos atuais dos produtos vinculados','#397ef9'],['CUSTOS EXTRAS',cost-parts,'Logística e outras despesas','#f7ad40'],['PREGÕES CADASTRADOS',state.bids.length,'Contratos na base fictícia','#56dbfb']];
const metrics=cards.map((c,i)=>`<div class="fincard" style="--accent:${c[3]}"><small>${c[0]}</small><strong class="num">${i===7?c[1]:i===3||i===4?moneyVisible?pct(c[1]):'••••••':moneyMask(c[1])}</strong><span>${c[2]}</span></div>`).join('');
const statusGroups=['Pendente','Em andamento','Entregue'].map(s=>({label:s,count:activeClients().filter(c=>c.status===s).length}));const byBid=state.bids.map(b=>({name:b.number,used:b.items.reduce((n,i)=>n+itemUsage(i.id),0),all:b.items.reduce((n,i)=>n+i.qty,0)})).filter(x=>x.all>0);
return `<div class="finance">${viewHeader('Painel de Performance Financeira','Valor vigente, custos, margem, markup e controle operacional.',`<button class="btn dark" data-action="toggleMoney">${moneyVisible?'◉ Ocultar':'◉ Mostrar'} valores fictícios</button><button class="btn dark" data-route="relatorios">Relatórios</button>`)}<div class="fin-intro"><small>VISÃO FINANCEIRA CONSOLIDADA</small><h2>Valor vigente, custos e resultado, ligados aos registros de exemplo.</h2><p>Os cálculos usam os itens efetivamente vinculados a atendimentos. As alterações de custo dos produtos repercutem aqui e nos relatórios automaticamente. Todos os valores são inventados.</p></div><div class="fincards">${metrics}</div><div class="darkgrid"><div class="darkpanel"><div class="panelhead"><div><h2>Resumo operacional</h2><small>Indicadores calculados na base de exemplo</small></div><span class="badge">ATUALIZADO</span></div><div class="mini-stats">${[['Atendimentos',activeClients().length],['Produtos cadastrados',state.products.filter(p=>p.active).length],['Itens fornecidos',activeClients().flatMap(c=>c.supplies).length],['Pregões vigentes',state.bids.filter(b=>b.status==='Vigente').length]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div><div style="margin-top:15px"><h2>Distribuição por andamento</h2><div class="actions">${statusGroups.map(x=>`<span class="badge">${x.label}: ${x.count}</span>`).join('')}</div></div></div><div class="darkpanel"><div class="panelhead"><div><h2>Consumo por pregão</h2><small>Vínculos realizados x quantidade contratada</small></div></div>${byBid.map(x=>`<div class="chartbar"><div><span>${x.name}</span><strong>${x.used} / ${x.all}</strong></div><div class="bartrack"><i style="width:${100*x.used/x.all}%"></i></div></div>`).join('')}<div style="margin-top:17px"><h2>Valor contratado total</h2><p class="num" style="margin:6px 0;font-size:20px">${moneyMask(totalContracts())}</p><small>Indicador bruto da proposta — não equivale ao valor vigente.</small></div></div></div><div class="darkpanel"><div class="panelhead"><div><h2>Últimos atendimentos</h2><small>Acompanhamento operacional</small></div><button class="btn dark small" data-route="cadastros">Ver cadastros</button></div>${table(['Atendimento','Contrato','Status','Valor vigente','Detalhes'],activeClients().slice(-5).reverse().map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(bidFor(c.bidId)?.contract)}</td><td>${statusBadge(c.status)}</td><td>${moneyMask(priceOf(c))}</td><td><button class="tbl-btn" data-action="client" data-id="${c.id}">Abrir</button></td></tr>`))}</div></div>`;
}
function cadastros(){if(selectedClient)return clientDetail(selectedClient);const q=filters.clients.toLowerCase(),rows=activeClients().filter(c=>(c.name+' '+c.city+' '+(bidFor(c.bidId)?.contract||'')).toLowerCase().includes(q)&&(filters.status==='Todos'||c.status===filters.status));return `<div class="page">${viewHeader('Cadastros','Gestão de atendimentos, dados gerais e vínculos com contratos.',editable()?'<button class="btn primary" data-route="novo">+ Novo atendimento</button>':'')}
<div class="grid4" style="margin-bottom:16px">${[['Total',activeClients().length],['Pendentes',activeClients().filter(c=>c.status==='Pendente').length],['Em andamento',activeClients().filter(c=>c.status==='Em andamento').length],['Finalizados',activeClients().filter(c=>c.status==='Entregue').length]].map(([a,b])=>`<div class="stat"><small>${a}</small><strong>${b}</strong><span>Registros fictícios</span></div>`).join('')}</div>${panel('Consulta de atendimentos',`<div class="toolbar"><input id="clientSearch" placeholder="Buscar nome, cidade ou contrato" value="${esc(filters.clients)}"><select id="clientStatus">${['Todos','Pendente','Em andamento','Entregue'].map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn secondary" data-action="resetFilters">Limpar</button></div>`+table(['Atendimento','Cidade','Pregão / contrato','Situação','Fornecimentos','Valor vigente','Ações'],rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="subtext">${esc(c.date)}</div></td><td>${esc(c.city)}</td><td>${esc(bidFor(c.bidId)?.number||'—')}<div class="subtext">${esc(bidFor(c.bidId)?.contract||'—')}</div></td><td>${statusBadge(c.status)}</td><td>${c.supplies.length}</td><td class="num">${money(priceOf(c))}</td><td><button class="tbl-btn" data-action="client" data-id="${c.id}">Abrir ficha</button></td></tr>`)))}</div>`}
function novo(){return `<div class="page">${viewHeader('Novo atendimento','Cadastro e vínculo com um pregão existente.')}<div class="hint">Campos e pessoas inteiramente fictícios. O cadastro é salvo apenas neste navegador e não alimenta nenhuma base empresarial.</div>${panel('Dados do atendimento',`<form id="createClient"><div class="formgrid cols3"><label>Identificação do atendimento *<input required name="name" placeholder="Atendimento Exemplo 008" maxlength="70"></label><label>Cidade *<input name="city" required placeholder="Cidade Exemplo" maxlength="70"></label><label>Data<input type="date" name="date" value="2026-10-27"></label><label>Pregão / Contrato *<select name="bidId" required>${state.bids.filter(x=>x.status==='Vigente').map(b=>`<option value="${b.id}">${esc(b.number)} · ${esc(b.contract)}</option>`).join('')}</select></label><label>Status<select name="status">${['Pendente','Em andamento','Entregue'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Responsável pelo atendimento<input value="Equipe Demo" readonly></label><label class="wide">Observações<textarea name="notes" placeholder="Observações fictícias, sem dados pessoais reais"></textarea></label></div><div class="formfoot"><button type="button" class="btn secondary" data-route="cadastros">Cancelar</button><button type="submit" class="btn primary" ${editable()?'':'disabled'}>Salvar atendimento</button></div></form>`)}</div>`}
function clientDetail(cid){const c=state.clients.find(x=>x.id===cid && !x.deleted);if(!c){selectedClient=null;return cadastros()}const b=bidFor(c.bidId);const tabs=['resumo','fornecimentos','financeiro'];const title=['Resumo','Produtos fornecidos / itens vigentes','Custos e valores'];let body='';
if(detailTab==='resumo'){body=`<div class="detail-list"><div><small>Identificação</small><strong>${esc(c.name)}</strong></div><div><small>Status</small>${statusBadge(c.status)}</div><div><small>Cidade</small><strong>${esc(c.city)}</strong></div><div><small>Data de abertura</small><strong>${esc(c.date)}</strong></div><div><small>Pregão</small><strong>${esc(b?.number)}</strong></div><div><small>Contrato</small><strong>${esc(b?.contract)}</strong></div></div><div class="hint" style="margin-top:14px">${esc(c.notes||'Nenhuma observação cadastrada.')}</div><div class="actions">${editable()?`<button class="btn secondary" data-action="editClient" data-id="${c.id}">Editar dados</button><button class="btn danger" data-action="deleteClient" data-id="${c.id}" ${onlyAdmin()?'':'disabled'}>Mover para lixeira</button>`:''}</div>`}
if(detailTab==='fornecimentos'){const rows=c.supplies.map(s=>{const p=productFor(s.productId),i=itemFor(s.itemId);return `<tr><td>${esc(p?.code)}</td><td>${esc(p?.name||'Produto não encontrado')}</td><td>${esc(s.size)}</td><td>${esc(i?.number)}</td><td>${s.qty}</td><td class="num">${money((p?.cost||0)*s.qty)}</td><td>${editable()?`<button class="tbl-btn" data-action="editSupply" data-id="${s.id}" data-cid="${c.id}">Editar</button>`:'—'}</td></tr>`});body=`<div class="hint">O item vigente é identificado pela descrição/categoria do contrato. <strong>O tamanho físico do produto não altera o número do item.</strong> O saldo de cada item é conferido antes de um vínculo novo.</div><div class="actions" style="margin-bottom:12px">${editable()?`<button class="btn primary" data-action="addSupply" data-id="${c.id}">+ Vincular produto / item</button>`:''}<button class="btn secondary" data-action="bid" data-id="${c.bidId}">Ver saldo do pregão</button></div>${table(['Código','Produto','Tamanho','Item vigente','Qtd.','Custo','Ação'],rows)}`}
if(detailTab==='financeiro'){const curr=priceOf(c),cost=costOf(c);body=`<div class="grid3"><div class="stat"><small>Valor vigente</small><strong>${money(curr)}</strong><span>Itens contratados distintos vinculados</span></div><div class="stat"><small>Custo total</small><strong>${money(cost)}</strong><span>Custos atualizados + adicionais</span></div><div class="stat"><small>Margem</small><strong>${money(curr-cost)}</strong><span>${curr?pct((curr-cost)/curr*100):'Sem item vigente'}</span></div></div><div class="hint" style="margin-top:15px">A atualização do custo no catálogo repercute automaticamente também em atendimentos já vinculados. O valor unitário contratado permanece inalterado.</div>${table(['Produto','Custo atual x quantidade','Logística','Outros'],c.supplies.map(s=>`<tr><td>${esc(productFor(s.productId)?.name)}</td><td>${money((productFor(s.productId)?.cost||0)*s.qty)}</td><td>${money(s.logistics)}</td><td>${money(s.other)}</td></tr>`))}`}
return `<div class="page">${viewHeader('Ficha do atendimento','Dados fictícios · vínculo de fornecimentos · rastreabilidade.',`<button class="btn secondary" data-action="backClients">← Voltar à lista</button>`)}${panel(esc(c.name),`<div class="actions"><span class="badge">${esc(b?.number||'')}</span><span class="badge">${esc(b?.contract||'')}</span>${statusBadge(c.status)}</div><div class="tabs">${tabs.map((t,i)=>`<button class="tab ${detailTab===t?'active':''}" data-action="clientTab" data-tab="${t}">${title[i]}</button>`).join('')}</div>${body}`)}</div>`;
}
function produtos(){const q=filters.products.toLowerCase();let rows=state.products.filter(p=>p.active &&(p.code+' '+p.name+' '+p.category+' '+p.supplier).toLowerCase().includes(q));return `<div class="page">${viewHeader('Produtos','Catálogo de componentes, custos e histórico de fornecimento.',editable()?'<button class="btn primary" data-action="newProduct">+ Cadastrar produto</button>':'')}
<div class="grid4" style="margin-bottom:16px">${[['Produtos ativos',state.products.filter(p=>p.active).length],['Categorias',new Set(state.products.filter(p=>p.active).map(p=>p.category)).size],['Fornecedores',supplierCount()],['Produtos em uso',new Set(activeClients().flatMap(c=>c.supplies.map(s=>s.productId))).size]].map(([a,b])=>`<div class="stat"><small>${a}</small><strong>${b}</strong><span>Base fictícia</span></div>`).join('')}</div>${panel('Gerenciamento de produtos',`<div class="toolbar"><input id="productSearch" placeholder="Buscar código, descrição, categoria ou fornecedor" value="${esc(filters.products)}"><button data-action="clearProductFilter" class="btn secondary">Limpar</button></div>`+table(['Código','Descrição','Categoria','Tamanho padrão','Fornecedor','Custo atual','Em uso','Ações'],rows.map(p=>`<tr><td><strong>${esc(p.code)}</strong></td><td>${esc(p.name)}</td><td>${esc(p.category)}</td><td>${esc(p.size)}</td><td>${esc(p.supplier)}</td><td class="num">${money(p.cost)}</td><td>${activeClients().flatMap(c=>c.supplies).filter(s=>s.productId===p.id).length}</td><td>${editable()?`<button class="tbl-btn" data-action="editProduct" data-id="${p.id}">Editar</button> ${onlyAdmin()?`<button class="tbl-btn" data-action="deleteProduct" data-id="${p.id}">Excluir</button>`:''}`:'Consulta'}</td></tr>`)))}<div class="hint" style="margin-bottom:0">Nesta demonstração, mudar o custo de um produto atualiza automaticamente os resultados dos atendimentos antigos que utilizam seu código. Os dados não saem deste navegador.</div></div>`}
function performance(){const data=state.products.filter(p=>p.active).map(p=>{const arr=activeClients().flatMap(c=>c.supplies.filter(s=>s.productId===p.id));const count=arr.reduce((n,s)=>n+s.qty,0);return {...p,used:count,spend:count*p.cost}}).sort((a,b)=>b.used-a.used);const total=data.reduce((x,p)=>x+p.spend,0);const max=Math.max(1,...data.map(p=>p.used));const top=data.slice(0,6);const categories=Array.from(new Set(data.map(p=>p.category))).map(category=>({category,quantity:data.filter(x=>x.category===category).reduce((n,x)=>n+x.used,0)}));const m=Math.max(1,...categories.map(x=>x.quantity));
return `<div class="page">${viewHeader('Performance de Produtos','Análise de consumo, custos e participação por categoria.',`<button class="btn secondary" data-route="produtos">Ver catálogo</button>`)}<div class="grid4" style="margin-bottom:16px">${[['Itens fornecidos',data.reduce((n,p)=>n+p.used,0)],['Produtos com saída',data.filter(p=>p.used>0).length],['Categorias utilizadas',categories.filter(x=>x.quantity>0).length],['Custo dos fornecimentos',money(total)]].map(([a,b])=>`<div class="stat"><small>${a}</small><strong style="font-size:${String(b).length>11?17:24}px">${b}</strong><span>Calculado em tempo real</span></div>`).join('')}</div><div class="grid2">${panel('Ranking de produtos utilizados',table(['Produto','Categoria','Qtd. vinculada','Custo total'],top.map(x=>`<tr><td>${esc(x.code)} · ${esc(x.name)}</td><td>${esc(x.category)}</td><td>${x.used}</td><td>${money(x.spend)}</td></tr>`)))}${panel('Consumo por categoria',categories.map(x=>`<div style="margin-bottom:18px"><div style="display:flex;justify-content:space-between;margin-bottom:6px"><strong>${esc(x.category)}</strong><span>${x.quantity} unidade(s)</span></div><div class="bartrack" style="background:#e8f0f9"><i style="width:${100*x.quantity/m}%"></i></div></div>`).join(''))}</div>${panel('Alertas e regras de custo',`<div class="hint">Custo de produto = custo unitário atual × quantidade fornecida. O valor contratado é buscado no item vigente do pregão. O tamanho serve apenas à identificação do produto físico.</div><div class="actions"><button class="btn secondary" data-route="relatorios">Emitir relatório de produtos</button><button class="btn secondary" data-route="produtos">Atualizar custo no catálogo</button></div>`)}</div>`}
function pregoes(){if(selectedBid)return bidDetail(selectedBid);const q=filters.bids.toLowerCase();const rows=state.bids.filter(b=>(b.number+b.contract+b.agency).toLowerCase().includes(q));return `<div class="page">${viewHeader('Pregões / Contratos','Itens ganhos, quantidade contratada, saldo e valor vigente.',editable()?'<button class="btn primary" data-action="newBid">+ Novo pregão</button>':'')}
<div class="grid4" style="margin-bottom:16px">${[['Pregões',state.bids.length],['Vigentes',state.bids.filter(x=>x.status==='Vigente').length],['Itens cadastrados',state.bids.reduce((x,b)=>x+b.items.length,0)],['Atendimentos vinculados',activeClients().filter(c=>c.supplies.some(x=>x.itemId)).length]].map(([a,b])=>`<div class="stat"><small>${a}</small><strong>${b}</strong><span>Contratos fictícios</span></div>`).join('')}</div>${panel('Lista de pregões',`<div class="toolbar"><input id="bidSearch" placeholder="Buscar pregão, órgão ou contrato" value="${esc(filters.bids)}"><button class="btn secondary" data-action="clearBidFilter">Limpar</button></div>`+table(['Pregão','Órgão','Contrato','Itens','Qtde contratada','Valor total','Status','Detalhes'],rows.map(b=>`<tr><td><strong>${esc(b.number)}</strong></td><td>${esc(b.agency)}</td><td>${esc(b.contract)}</td><td>${b.items.length}</td><td>${b.items.reduce((n,i)=>n+i.qty,0)}</td><td>${money(b.items.reduce((n,i)=>n+i.qty*i.value,0))}</td><td>${statusBadge(b.status)}</td><td><button class="tbl-btn" data-action="bid" data-id="${b.id}">Abrir</button></td></tr>`)))}<div class="hint" style="margin-bottom:0">O saldo de cada item é calculado com base na quantidade ganha e nos vínculos realizados. A versão de portfólio não importa contratos reais nem PDFs da empresa.</div></div>`}
function bidDetail(idBid){const b=bidFor(idBid);if(!b){selectedBid=null;return pregoes()}const active=activeClients().filter(c=>c.bidId===b.id);const total=b.items.reduce((n,i)=>n+i.qty*i.value,0),vig=active.reduce((n,c)=>n+priceOf(c),0);const tabs=['itens','atendimentos','financeiro'];let body='';
if(bidTab==='itens'){body=`<div class="hint">Controle de saldo por item: vínculos bloqueados ao alcançar a quantidade ganha. <strong>O tamanho do componente não altera a identificação do item.</strong></div>${table(['Item','Descrição resumida','Qtd. ganha','Vinculados','Saldo','Valor unitário','Situação'],b.items.map(i=>{const used=itemUsage(i.id);return `<tr><td><strong>${esc(i.number)}</strong></td><td>${esc(i.description)}</td><td>${i.qty}</td><td>${used}</td><td><strong>${i.qty-used}</strong></td><td>${money(i.value)}</td><td>${i.qty-used<=0?statusBadge('Encerrado'):statusBadge('Vigente')}</td></tr>`}))}<div class="actions" style="margin-top:15px">${editable()?`<button class="btn secondary" data-action="newItem" data-id="${b.id}">+ Adicionar item fictício</button>`:''}</div>`}
if(bidTab==='atendimentos'){body=table(['Atendimento','Situação','Itens vigentes vinculados','Valor vigente','Detalhes'],active.map(c=>`<tr><td>${esc(c.name)}</td><td>${statusBadge(c.status)}</td><td>${new Set(c.supplies.map(s=>s.itemId)).size}</td><td>${money(priceOf(c))}</td><td><button class="tbl-btn" data-action="client" data-id="${c.id}">Abrir ficha</button></td></tr>`))}
if(bidTab==='financeiro'){const cost=active.reduce((n,c)=>n+costOf(c),0);body=`<div class="grid3"><div class="stat"><small>Valor total contratado</small><strong>${money(total)}</strong></div><div class="stat"><small>Valor vigente</small><strong>${money(vig)}</strong></div><div class="stat"><small>Saldo não vigente</small><strong>${money(Math.max(0,total-vig))}</strong></div><div class="stat"><small>Custos atuais</small><strong>${money(cost)}</strong></div><div class="stat"><small>Margem vigente</small><strong>${money(vig-cost)}</strong></div><div class="stat"><small>Margem %</small><strong>${vig?pct((vig-cost)/vig*100):'—'}</strong></div></div><div class="hint" style="margin-top:14px">Valor contratado não se altera quando um produto tem seu custo atualizado. O custo dos atendimentos é recalculado automaticamente.</div>`}
return `<div class="page">${viewHeader(esc(b.number),`Contrato ${esc(b.contract)} · ${esc(b.agency)} · ${esc(b.process)}`,`<button class="btn secondary" data-action="backBids">← Todos os pregões</button>`)}<div class="grid4" style="margin-bottom:16px">${[['Situação',b.status],['Itens ganhos',b.items.length],['Atendimentos',active.length],['Saldo total de itens',b.items.reduce((n,i)=>n+i.qty-itemUsage(i.id),0)]].map(([a,x])=>`<div class="stat"><small>${a}</small><strong style="font-size:20px">${x}</strong></div>`).join('')}</div>${panel('Detalhes do contrato',`<div class="tabs">${tabs.map((t,i)=>`<button class="tab ${bidTab===t?'active':''}" data-action="bidTab" data-tab="${t}">${['Itens ganhos e saldo','Atendimentos vinculados','Resumo financeiro'][i]}</button>`).join('')}</div>${body}`)}</div>`;
}
function reportData(){const all=activeClients();if(reportType==='produtos')return {heads:['Código','Produto','Categoria','Quantidade vinculada','Custo atual'],rows:state.products.filter(p=>p.active).map(p=>[p.code,p.name,p.category,all.flatMap(c=>c.supplies).filter(s=>s.productId===p.id).reduce((n,s)=>n+s.qty,0),money(p.cost)])};if(reportType==='atendimentos')return {heads:['Atendimento','Contrato','Status','Fornecimentos','Custo total','Valor vigente'],rows:all.map(c=>[c.name,bidFor(c.bidId)?.contract||'',c.status,c.supplies.length,money(costOf(c)),money(priceOf(c))])};return {heads:['Pregão','Contrato','Itens','Quantidade ganha','Quantidade utilizada','Valor contratado','Valor vigente','Custo atualizado'],rows:state.bids.map(b=>[b.number,b.contract,b.items.length,b.items.reduce((n,i)=>n+i.qty,0),b.items.reduce((n,i)=>n+itemUsage(i.id),0),money(b.items.reduce((n,i)=>n+i.qty*i.value,0)),money(all.filter(c=>c.bidId===b.id).reduce((n,c)=>n+priceOf(c),0)),money(all.filter(c=>c.bidId===b.id).reduce((n,c)=>n+costOf(c),0))])}}
function relatorios(){const r=reportData();return `<div class="page">${viewHeader('Relatórios','Visualização e exportação de registros fictícios, calculados a partir da demo.',`<button class="btn secondary" data-action="print">Imprimir / Salvar em PDF</button><button class="btn primary" data-action="exportCsv">Exportar CSV</button>`)}<div class="hint">Nesta versão pública, use <strong>Imprimir / Salvar em PDF</strong> para gerar PDF pelo navegador. Não reproduz o motor de relatórios do sistema desktop.</div>${panel('Tipo de relatório',`<div class="actions">${[['pregao','Por pregão'],['atendimentos','Por atendimento'],['produtos','Performance de produtos']].map(([v,n])=>`<button class="btn chip ${reportType===v?'selected':''}" data-action="reportType" data-type="${v}">${n}</button>`).join('')}</div>`)}${panel('Prévia do relatório',`<div class="panelhead"><div><h2>${reportType==='pregao'?'Resumo de contratos':reportType==='atendimentos'?'Acompanhamento de atendimentos':'Ranking de produtos'}</h2><p class="subtext">Gerado com a base fictícia desta sessão · ${new Date().toLocaleDateString('pt-BR')}</p></div><span class="badge">${r.rows.length} linhas</span></div>`+table(r.heads,r.rows.map(line=>`<tr>${line.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`)))}</div>`}
function auditoria(){const q=filters.audit.toLowerCase(),events=state.audit.filter(x=>(x.actor+' '+x.area+' '+x.description).toLowerCase().includes(q));return `<div class="page">${viewHeader('Auditoria','Histórico de operações executadas na demonstração.')}<div class="hint">Eventos gravados apenas nesta sessão de demonstração. O sistema corporativo possui controle de auditoria próprio que não está conectado aqui.</div>${panel('Registros de alterações',`<div class="toolbar"><input id="auditSearch" placeholder="Filtrar área, usuário ou ação" value="${esc(filters.audit)}"></div>`+table(['Data / hora','Usuário','Módulo','Ação'],events.map(x=>`<tr><td>${fmtDate(x.at)}</td><td>${esc(x.actor)}</td><td>${esc(x.area)}</td><td>${esc(x.description)}</td></tr>`)))}</div>`}
function lixeira(){return `<div class="page">${viewHeader('Lixeira','Exclusão lógica de cadastros e produtos, com possibilidade de restauração.')}<div class="hint">Excluir não apaga imediatamente um registro. A restauração é limitada aos dados fictícios desta demonstração.</div>${panel('Atendimentos excluídos',table(['Atendimento','Cidade','Contrato','Ação'],state.clients.filter(c=>c.deleted).map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.city)}</td><td>${esc(bidFor(c.bidId)?.contract)}</td><td><button class="btn secondary small" data-action="restoreClient" data-id="${c.id}" ${onlyAdmin()?'':'disabled'}>Restaurar</button></td></tr>`)))}${panel('Produtos excluídos',table(['Código','Produto','Ação'],state.products.filter(p=>!p.active).map(p=>`<tr><td>${esc(p.code)}</td><td>${esc(p.name)}</td><td><button class="btn secondary small" data-action="restoreProduct" data-id="${p.id}" ${onlyAdmin()?'':'disabled'}>Restaurar</button></td></tr>`)))}</div>`}
function backup(){return `<div class="page">${viewHeader('Backup da demonstração','Exportação local e restauração da base de exemplo.')}<div class="grid2">${panel('Exportar dados fictícios',`<p>Salve uma cópia JSON dos registros desta demonstração, incluindo atendimentos, produtos, pregões e auditoria.</p><div class="actions"><button class="btn primary" data-action="exportJson">Baixar arquivo JSON</button></div><p class="subtext">Nenhuma consulta a banco empresarial é realizada.</p>`)}${panel('Reiniciar demonstração',`<p>Apaga as alterações feitas neste navegador e restaura o conjunto inicial de dados fictícios.</p><button class="btn danger" data-action="reset">Restaurar base inicial</button><p class="subtext">Essa ação não afeta os sistemas reais.</p>`)}</div>${panel('Notas técnicas',`<ul class="lightlist"><li>Frontend estático HTML, CSS e JavaScript; não usa MySQL.</li><li>Alterações armazenadas localmente no navegador para você experimentar.</li><li>O sistema desktop real é desenvolvido com Python, CustomTkinter e MySQL.</li><li>Backups operacionais do sistema real não são disponibilizados publicamente.</li></ul>`)}</div>`}
function usuarios(){return `<div class="page">${viewHeader('Usuários e permissões','Exemplo de administração de acessos com três níveis.',onlyAdmin()?'<button class="btn primary" data-action="newUser">+ Novo usuário fictício</button>':'') }<div class="hint">Troque o perfil no canto superior direito para experimentar as diferenças entre <strong>Administrador</strong>, <strong>Usuário</strong> e <strong>Consulta</strong>. Não há login verdadeiro nesta demonstração.</div>${panel('Perfis cadastrados',table(['Identificação','Nível','Situação','Acesso'],state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${statusBadge(u.role==='admin'?'Administrador':u.role==='user'?'Usuário':'Consulta')}</td><td>${statusBadge(u.status)}</td><td>${u.role==='admin'?'Todos os módulos':u.role==='user'?'Operação sem administração':'Somente leitura'}</td></tr>`)))}${panel('Permissões por nível',table(['Operação','Administrador','Usuário','Consulta'],[['Consultar dados','Sim','Sim','Sim'],['Criar e editar','Sim','Sim','Não'],['Excluir e restaurar','Sim','Não','Não'],['Gerenciar usuários','Sim','Não','Não']].map(x=>`<tr>${x.map(t=>`<td>${t}</td>`).join('')}</tr>`)))}</div>`}
// Dialogs and actions
function openModal(title,body,actions='',subtitle=''){const host=$('#modalHost');host.innerHTML=`<div class="modal-bg" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalheader"><div><h2>${esc(title)}</h2>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div><button class="close" data-action="close" aria-label="Fechar">×</button></div><div class="modalbody">${body}</div>${actions?`<div class="modalfooter">${actions}</div>`:''}</div></div>`;host.querySelector('#overlay').addEventListener('click',ev=>{if(ev.target.id==='overlay')closeModal()})}
function closeModal(){$('#modalHost').innerHTML=''}
function productDialog(pid){const p=state.products.find(x=>x.id===pid),newOne=!p;const form=`<form id="productForm" data-id="${esc(pid||'')}"><div class="formgrid"><label>Código *<input name="code" required maxlength="28" value="${esc(p?.code||'')}"></label><label>Categoria<select name="category">${['Componentes','Interfaces','Pés','Acessórios','Conjunto','Outros'].map(x=>`<option ${p?.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="wide">Descrição do produto *<input name="name" required maxlength="120" value="${esc(p?.name||'')}"></label><label>Fornecedor fictício *<input name="supplier" required maxlength="70" value="${esc(p?.supplier||'Fabricante Exemplo A')}"></label><label>Tamanho padrão<input name="size" value="${esc(p?.size||'Único')}"></label><label>Custo unitário atual (R$) *<input name="cost" type="number" min="0" step="0.01" value="${p?.cost??0}" required></label><label>Estado<input disabled value="${p?.active===false?'Inativo':'Ativo'}"></label></div><div class="formfoot"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button class="btn primary" type="submit">${newOne?'Cadastrar produto':'Salvar alterações'}</button></div></form>`;openModal(newOne?'Cadastrar produto fictício':'Editar produto e custo atual',form,'','Uma alteração de custo repercute nos vínculos existentes.')}
function clientDialog(cid){const c=state.clients.find(x=>x.id===cid),b=bidFor(c.bidId);openModal('Editar atendimento',`<form id="editClientForm" data-id="${cid}"><div class="formgrid"><label>Atendimento *<input name="name" required value="${esc(c.name)}"></label><label>Cidade<input name="city" value="${esc(c.city)}"></label><label>Status<select name="status">${['Pendente','Em andamento','Entregue'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Contrato<input readonly value="${esc(b?.contract||'')}"></label><label class="wide">Observações<textarea name="notes">${esc(c.notes)}</textarea></label></div><div class="formfoot"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button class="btn primary" type="submit">Salvar</button></div></form>`)}
function supplyDialog(cid,sid){const c=state.clients.find(x=>x.id===cid),s=c.supplies.find(x=>x.id===sid),b=bidFor(c.bidId);const first=b.items[0];const selected=s?.itemId||first?.id;const items=b.items.map(i=>`<option value="${i.id}" ${selected===i.id?'selected':''}>Item ${esc(i.number)} · ${esc(i.description)} · saldo ${i.qty-itemUsage(i.id)} / ${i.qty}</option>`).join('');const prodOpts=state.products.filter(p=>p.active).map(p=>`<option value="${p.id}" ${s?.productId===p.id?'selected':''}>${esc(p.code)} · ${esc(p.name)}</option>`).join('');openModal(s?'Editar fornecimento':'Vincular produto ao item vigente',`<form id="supplyForm" data-cid="${cid}" data-sid="${esc(sid||'')}"><div class="hint">Itens do pregão ${esc(b.number)}. Tamanho é atributo físico e não interfere na identificação contratual do item.</div><div class="formgrid"><label class="wide">Item vigente do contrato *<select name="itemId">${items}</select></label><label class="wide">Produto cadastrado *<select name="productId">${prodOpts}</select></label><label>Quantidade física<input name="qty" type="number" min="1" step="1" value="${s?.qty||1}" required></label><label>Tamanho físico<input name="size" value="${esc(s?.size||'Único')}" maxlength="15"></label><label>Logística (R$)<input name="logistics" type="number" min="0" step="0.01" value="${s?.logistics||0}"></label><label>Outros custos (R$)<input name="other" type="number" min="0" step="0.01" value="${s?.other||0}"></label></div><div class="formfoot">${s?`<button type="button" class="btn danger" data-action="removeSupply" data-cid="${cid}" data-id="${sid}">Remover vínculo</button>`:''}<button type="button" class="btn secondary" data-action="close">Cancelar</button><button class="btn primary" type="submit">${s?'Salvar':'Vincular item'}</button></div></form>`) }
function newBidDialog(){openModal('Novo pregão / contrato',`<form id="bidForm"><div class="formgrid"><label>Número do pregão *<input name="number" placeholder="PE 085/2026" required></label><label>Contrato *<input name="contract" placeholder="CT-055/2026" required></label><label>Órgão fictício *<input name="agency" value="Instituição Pública Exemplo" required></label><label>Processo<input name="process" placeholder="PR-250/2026"></label><label>Status<select name="status"><option>Vigente</option><option>Encerrado</option></select></label></div><div class="formfoot"><button class="btn secondary" type="button" data-action="close">Cancelar</button><button class="btn primary" type="submit">Cadastrar</button></div></form>`,'','Você poderá incluir itens contratados depois.')}
function newItemDialog(bidId){openModal('Novo item do contrato',`<form id="itemForm" data-bid="${bidId}"><div class="formgrid"><label>Item *<input name="number" required placeholder="04"></label><label>Categoria *<select name="category">${['Conjunto','Componentes','Pés','Interfaces','Acessórios','Outros'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="wide">Descrição resumida *<input name="description" required placeholder="Componente demonstrativo"></label><label>Quantidade ganha *<input name="qty" required type="number" min="1" step="1" value="5"></label><label>Valor unitário contratado (R$) *<input name="value" required type="number" min="0.01" step="0.01" value="1500"></label></div><div class="formfoot"><button class="btn secondary" type="button" data-action="close">Cancelar</button><button class="btn primary" type="submit">Adicionar item</button></div></form>`)}
function userDialog(){openModal('Criar usuário fictício',`<form id="userForm"><div class="formgrid"><label>Nome de identificação *<input required name="name" placeholder="Operador Exemplo"></label><label>Nível<select name="role"><option value="user">Usuário</option><option value="guest">Consulta</option><option value="admin">Administrador</option></select></label></div><div class="formfoot"><button class="btn secondary" data-action="close" type="button">Cancelar</button><button class="btn primary" type="submit">Criar usuário de demonstração</button></div></form>`)}
function fileDownload(filename,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(){const r=reportData(),text=[r.heads,...r.rows].map(line=>line.map(cell=>'"'+String(cell).replace(/"/g,'""')+'"').join(';')).join('\r\n');fileDownload('poiato_relatorio_demo_'+reportType+'.csv','\ufeff'+text,'text/csv;charset=utf-8');note('Relatórios','Exportação de relatório fictício ('+reportType+')');toast('CSV com dados fictícios exportado')}
function exportJson(){fileDownload('poiato_gestao_demo_backup.json',JSON.stringify({demo:true,savedAt:new Date().toISOString(),data:state},null,2),'application/json');note('Backup','Exportou JSON fictício da demonstração');toast('Backup local da demo baixado')}
function resetDemo(){if(!confirm('Restaurar a base fictícia inicial? Alterações locais serão perdidas.'))return;state=fresh();save();selectedBid=null;selectedClient=null;closeModal();navigate('dashboard');toast('Base da demonstração restaurada')}
function act(btn){const a=btn.dataset.action,ident=btn.dataset.id;if(!a)return;
switch(a){case 'toggleMoney':moneyVisible=!moneyVisible;render();break;
case 'client':selectedClient=ident;detailTab='resumo';selectedBid=null;page='cadastros';render();break;
case 'clientTab':detailTab=btn.dataset.tab;render();break;
case 'backClients':selectedClient=null;page='cadastros';render();break;
case 'editClient':if(editable())clientDialog(ident);break;
case 'deleteClient':if(onlyAdmin()&&confirm('Mover este atendimento fictício para a lixeira?')){const c=state.clients.find(c=>c.id===ident);c.deleted=true;note('Cadastros','Atendimento fictício movido à lixeira');selectedClient=null;render();toast('Atendimento na lixeira')}break;
case 'restoreClient':if(onlyAdmin()){state.clients.find(x=>x.id===ident).deleted=false;note('Lixeira','Atendimento fictício restaurado');render();toast('Cadastro restaurado')}break;
case 'addSupply':if(editable())supplyDialog(ident);break;
case 'editSupply':if(editable())supplyDialog(btn.dataset.cid,ident);break;
case 'removeSupply':if(editable()&&confirm('Remover o vínculo fictício?')){const c=state.clients.find(c=>c.id===btn.dataset.cid);c.supplies=c.supplies.filter(s=>s.id!==ident);note('Fornecimentos','Produto desvinculado de atendimento fictício');closeModal();render();toast('Vínculo removido')}break;
case 'newProduct':if(editable())productDialog();break;
case 'editProduct':if(editable())productDialog(ident);break;
case 'deleteProduct':if(onlyAdmin()&&confirm('Mover este produto para a lixeira?')){state.products.find(x=>x.id===ident).active=false;note('Produtos','Produto excluído logicamente');render();toast('Produto movido para a lixeira')}break;
case 'restoreProduct':if(onlyAdmin()){state.products.find(x=>x.id===ident).active=true;note('Lixeira','Produto restaurado');render();toast('Produto restaurado')}break;
case 'clearProductFilter':filters.products='';render();break;
case 'bid':selectedBid=ident;selectedClient=null;bidTab='itens';page='pregoes';render();break;
case 'backBids':selectedBid=null;page='pregoes';render();break;
case 'bidTab':bidTab=btn.dataset.tab;render();break;
case 'clearBidFilter':filters.bids='';render();break;
case 'newBid':if(editable())newBidDialog();break;
case 'newItem':if(editable())newItemDialog(ident);break;
case 'newUser':if(onlyAdmin())userDialog();break;
case 'reportType':reportType=btn.dataset.type;render();break;
case 'exportCsv':exportCsv();break;
case 'print':window.print();break;
case 'exportJson':exportJson();break;
case 'reset':resetDemo();break;
case 'resetFilters':filters.clients='';filters.status='Todos';render();break;
case 'close':closeModal();break;
}}
function formSubmitted(form){const vals=Object.fromEntries(new FormData(form));if(!editable()&&form.id!=='userForm'){toast('Perfil de consulta: apenas visualização');return}
if(form.id==='createClient'){const c={id:id('c'),name:vals.name.trim(),city:vals.city.trim(),date:vals.date,bidId:vals.bidId,status:vals.status,notes:vals.notes||'',deleted:false,supplies:[]};state.clients.unshift(c);note('Cadastros','Atendimento fictício criado');selectedClient=c.id;page='cadastros';render();toast('Atendimento criado: agora você pode vincular itens')}
if(form.id==='editClientForm'){const c=state.clients.find(x=>x.id===form.dataset.id);Object.assign(c,{name:vals.name.trim(),city:vals.city.trim(),status:vals.status,notes:vals.notes||''});note('Cadastros','Dados de atendimento alterados');closeModal();render();toast('Cadastro atualizado')}
if(form.id==='productForm'){const previous=state.products.find(p=>p.id===form.dataset.id);const duplicate=state.products.some(p=>p.id!==previous?.id&&p.active&&p.code.toLowerCase()===vals.code.trim().toLowerCase());if(duplicate){toast('Código já existe entre produtos ativos');return}const obj={code:vals.code.trim(),name:vals.name.trim(),category:vals.category,size:vals.size||'Único',supplier:vals.supplier.trim(),cost:Number(vals.cost),active:true};if(previous)Object.assign(previous,obj);else state.products.unshift({id:id('p'),...obj});note('Produtos',previous?'Produto fictício alterado (custos recalculados)':'Produto fictício cadastrado');closeModal();render();toast(previous?'Custo atualizado em todos os vínculos':'Produto fictício cadastrado')}
if(form.id==='supplyForm'){const c=state.clients.find(x=>x.id===form.dataset.cid),current=c.supplies.find(x=>x.id===form.dataset.sid),selected=itemFor(vals.itemId);if(!selected||selected.bidId!==c.bidId){toast('Escolha um item do pregão do atendimento');return}const usedWithoutCurrent=activeClients().reduce((n,cli)=>n+Number(cli.supplies.some(s=>s.itemId===selected.id&&s.id!==current?.id)),0);const alreadyOnThisClient=c.supplies.some(s=>s.itemId===selected.id&&s.id!==current?.id);if(!alreadyOnThisClient&&usedWithoutCurrent>=selected.qty){toast('Item sem saldo contratual disponível');return}const obj={itemId:vals.itemId,productId:vals.productId,qty:Math.max(1,parseInt(vals.qty,10)||1),size:vals.size||'Único',logistics:Number(vals.logistics)||0,other:Number(vals.other)||0};if(current)Object.assign(current,obj);else c.supplies.push({id:id('s'),...obj});note('Fornecimentos',current?'Fornecimento fictício atualizado':'Item vigente vinculado a atendimento');closeModal();render();toast('Vínculo salvo; saldos e valores foram recalculados')}
if(form.id==='bidForm'){state.bids.unshift({id:id('b'),number:vals.number.trim(),contract:vals.contract.trim(),agency:vals.agency.trim(),process:vals.process.trim(),status:vals.status,items:[]});note('Pregões','Pregão fictício cadastrado');closeModal();render();toast('Pregão criado; inclua seus itens')}
if(form.id==='itemForm'){const b=bidFor(form.dataset.bid);b.items.push({id:id('i'),number:vals.number.trim(),description:vals.description.trim(),category:vals.category,qty:Number(vals.qty),value:Number(vals.value)});note('Pregões','Item fictício adicionado ao contrato');closeModal();render();toast('Item adicionado; saldo disponível')}
if(form.id==='userForm'){if(!onlyAdmin()){toast('Somente administradores gerenciam usuários');return}state.users.push({id:id('u'),name:vals.name.trim(),role:vals.role,status:'Ativo'});note('Usuários','Usuário fictício adicionado');closeModal();render();toast('Perfil de demonstração criado')}
}
function inputChanged(el){if(el.id==='clientSearch'){filters.clients=el.value;render();refocus('#clientSearch')}if(el.id==='clientStatus'){filters.status=el.value;render()}if(el.id==='productSearch'){filters.products=el.value;render();refocus('#productSearch')}if(el.id==='bidSearch'){filters.bids=el.value;render();refocus('#bidSearch')}if(el.id==='auditSearch'){filters.audit=el.value;render();refocus('#auditSearch')}}
function refocus(selector){const el=$(selector);if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-route]');if(nav){navigate(nav.dataset.route);return}const action=ev.target.closest('[data-action]');if(action)act(action)});
document.addEventListener('input',ev=>{if(['clientSearch','productSearch','bidSearch','auditSearch'].includes(ev.target.id))inputChanged(ev.target)});
document.addEventListener('change',ev=>{if(ev.target.id==='clientStatus')inputChanged(ev.target)});
document.addEventListener('submit',ev=>{ev.preventDefault();if(ev.target.matches('form'))formSubmitted(ev.target)});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal()});
$('#userRole').addEventListener('change',e=>{role=e.target.value;selectedBid=null;selectedClient=null;navigate('dashboard');toast('Perfil de demonstração: '+(role==='admin'?'Administrador':role==='user'?'Usuário':'Consulta'))});
$('#resetTop').onclick=resetDemo;
render();
